import { expect, expectTypeOf, assertType } from "./test/expect-shim.mjs";
import { createSingletonPromise, sleep } from "./src/promise.js";
{
{
let dummy = 0;
    const promise = createSingletonPromise(async () => {
        await sleep(10);
        dummy += 1;
        return dummy;
    });
    expect(dummy).toBe(0);
    await promise();
    expect(dummy).toBe(1);
    await promise();
    expect(await promise()).toBe(1);
    expect(dummy).toBe(1);
    await promise.reset();
    await promise();
    expect(dummy).toBe(2);
}
